def transform(grid):
    out = [row[:] for row in grid[:3]]
    # Layer 2 is the default; layer 8 overrides it, then layer 4 has priority.
    for start in (6, 9, 3):
        layer = grid[start:start+3]
        for r in range(3):
            for c in range(6):
                if grid[r][c] == 0 and layer[r][c] != 0:
                    out[r][c] = layer[r][c]
    return out
